def C(label,art=None,text=None):
 x={'label':label}
 if art:x['art']=art
 if text is not None:x['text']=text
 return x

def T(s):return C(s,text=s)
def A(name):return C(name,name)
def Q(prompt,options,answer=0,explain='',scene=None,cue='Choose the answer.',hint=None,narration=None):
 global serial;serial+=1
 x={'id':'task-'+str(serial),'mode':'choice','prompt':prompt,'cue':cue,'options':[T(o) if isinstance(o,str) else o for o in options],'answers':answer if isinstance(answer,list) else [answer],'explain':explain,'scene':scene or []}
 if hint:x['hint']=hint
 if narration:x['narration']=narration
 return x

def O(prompt,items,explain='',constraints=None,accepted=None):
 q=Q(prompt,[],explain=explain,cue='Tap cards in order. Undo to change your plan.');q.update(mode='order',items=[T(x) if isinstance(x,str) else x for x in items])
 if constraints:q['constraints']=constraints
 if accepted:q['accepted']=accepted
 return q

def M(prompt,opts,answers,explain,scene=None):
 q=Q(prompt,opts,answers,explain,scene,'Find every picture that follows the rule.');q['mode']='multi';return q

def S(a,b):
 return {'id':a['id']+'-steps','stages':[a,b],'guide':'Solve each step in order. The next cue follows your answer; pictures and text remain reference material.'}

def F(name,description,tasks):return {'name':name,'description':description,'tasks':tasks}
def subject(id,title,intro,guide,goals,previews):
 D[id]={'id':id,'title':title,'intro':intro,'guide':guide,'levels':[{'name':n,'goal':g,'preview':p,'families':[]} for (n,g),p in zip(goals,previews)]}
def put(id,l,*families):D[id]['levels'][l-1]['families']=list(families)
def feat(s='circle',f='plain',z='large'):return C(z+' '+f+' '+s,s+'-'+f+'-'+z)

