def P(prompt,opts,observation,question,answers,explain):
 a=Q(prompt,opts,explain='',cue='Choose a prediction. It is a guess to check, not a scored answer.');a['mode']='predict';a['observation']=observation
 return S(a,Q('Observed result: '+observation+'\n'+question,answers,explain=explain,cue='Use the observed result to choose an explanation.'))
