subject('stories','Stories & Feelings','Original stories with several possible helpful paths. A grown-up may narrate. Feelings are not right or wrong.','Ask what the character might need and what else could help. Respect boundaries. An emotion guess is a possibility, not a diagnosis. Story paths do not produce behavior scores.',[
 ('Notice','Notice an event and possible feelings'),('Respond','Link events, needs and help'),('Understand others','Consider two viewpoints and boundaries'),('Explore choices','Compare actions and possible consequences'),('Resolve','Plan for several needs'),('Consider possibilities','Handle uncertainty and tradeoffs')],['event → feeling','need → help','my view + your view','choice → consequence','two needs → plan','possible reason → question'])

def B(text,art,choices):
 global serial;serial+=1
 nodes={'start':{'text':text,'art':art,'options':[]}}
 for i,(label,result) in enumerate(choices):
  node='end'+str(i);nodes['start']['options'].append({'text':label,'to':node});nodes[node]={'text':result,'end':True}
 return {'id':'story-'+str(serial),'mode':'branch','nodes':nodes,'guide':'Explore one possible path, then try another. More than one choice may be helpful. No feeling is scored as wrong.'}

def B2(text,art,first,second):
 q=B(text,art,first)
 for i,node in enumerate([n for n in q['nodes'] if n!='start']):
  outcome=q['nodes'][node]['text'];q['nodes'][node]={'text':outcome,'cue':'What could help next?','options':[]}
  for j,(label,result) in enumerate(second):
   end=node+'-'+str(j);q['nodes'][node]['options'].append({'text':label,'to':end});q['nodes'][end]={'text':result,'end':True}
 return q
